FROZEN_NOW = datetime(2026, 3, 28, 23, 30, tzinfo=UTC)
LOCAL_TODAY = date(2026, 3, 29)


class TestSetRelativeDateAction(BloomerpBehaviorActionTestCase):
    """Verify clock-relative offsets, draft preservation, and editor contracts."""

    action = SET_RELATIVE_DATE
    auto_create_customers = False
    relative_model: type[models.Model]

    @classmethod
    def setUpClass(cls) -> None:
        """Create editable temporal fields alongside ineligible destination types."""
        super().setUpClass()
        fixtures = create_test_models(
            "bloomerp",
            {
                "RelativeDateRecord": {
                    "name": models.CharField(max_length=40),
                    "due_date": models.DateField(null=True, blank=True),
                    "due_at": models.DateTimeField(null=True, blank=True),
                    "clock": models.TimeField(null=True, blank=True),
                    "amount": models.IntegerField(null=True, blank=True),
                    "readonly_date": models.DateField(null=True, editable=False),
                    "created_at": models.DateTimeField(auto_now_add=True),
                },
                "RelativeDateLine": {
                    "record": models.ForeignKey(
                        "bloomerp.RelativeDateRecord",
                        on_delete=models.CASCADE,
                        related_name="lines",
                    ),
                    "due_date": models.DateField(null=True, blank=True),
                },
            },
            use_bloomerp_base=True,
        )
        cls.relative_model = fixtures["RelativeDateRecord"]

    def setUp(self) -> None:
        """Freeze the instant near midnight and the European DST transition."""
        super().setUp()
        self.enterContext(timezone.override("Europe/Amsterdam"))
        self.enterContext(
            patch(
                "bloomerp.form_behaviors.builtins.set_relative_date.timezone.now",
                return_value=FROZEN_NOW,
            )
        )

    def _field(self, name: str) -> ApplicationField:
        """Resolve a field from the dedicated temporal destination fixture."""
        return self.get_application_field(name, self.relative_model)

    def _scenario(
        self,
        name: str,
        *,
        target: str = "due_date",
        config: dict[str, Any],
        current: Any = None,
        expected: date | datetime | None = None,
        error: str | None = None,
    ) -> BehaviorActionScenario:
        """Describe one relative update or a configuration validation failure."""
        result = BehaviorResult(
            values=(FieldValueUpdate(field=target, value=expected),)
            if expected is not None
            else ()
        )
        return BehaviorActionScenario(
            name=name,
            context=BehaviorContext(
                values={"name": "trigger", target: current},
                listener_field="name",
                target_field=target,
            ),
            listener=self._field("name"),
            target=self._field(target),
            config=config,
            expected_result=result if error is None else None,
            expected_exception=ExpectedBehaviorActionException(ValidationError, error)
            if error is not None
            else None,
        )

    def get_test_scenarios(self) -> list[BehaviorActionScenario]:
        """Cover integer units, local-date anchoring, policies, and invalid input."""
        scenarios = [
            self._scenario(
                "positive days replace the existing date relative to today",
                config={"offset": 2},
                current=date(2001, 1, 1),
                expected=date(2026, 3, 31),
            ),
            self._scenario(
                "negative days use the current local date",
                config={"offset": "-1"},
                expected=date(2026, 3, 28),
            ),
            self._scenario(
                "zero days select today rather than the UTC date",
                config={"offset": 0},
                expected=LOCAL_TODAY,
            ),
            self._scenario(
                "date already equal to the result produces no update",
                config={"offset": 0},
                current=LOCAL_TODAY,
            ),
            self._scenario(
                "positive minutes replace an existing datetime across DST",
                target="due_at",
                config={"offset": 90, "write_policy": "always"},
                current=datetime(2001, 1, 1, tzinfo=UTC),
                expected=datetime(2026, 3, 29, 1, 0, tzinfo=UTC),
            ),
            self._scenario(
                "negative minutes select an earlier instant",
                target="due_at",
                config={"offset": "-31"},
                expected=datetime(2026, 3, 28, 22, 59, tzinfo=UTC),
            ),
            self._scenario(
                "zero minutes select the current instant",
                target="due_at",
                config={"offset": 0},
                expected=FROZEN_NOW,
            ),
            self._scenario(
                "datetime already equal to the result produces no update",
                target="due_at",
                config={"offset": 0},
                current=FROZEN_NOW,
            ),
        ]
        for target, expected, populated in (
            ("due_date", LOCAL_TODAY, "2020-01-01"),
            ("due_at", FROZEN_NOW, "2020-01-01T12:00:00+00:00"),
        ):
            for blank in (None, ""):
                scenarios.append(
                    self._scenario(
                        f"{target} fills {blank!r} under the empty-only policy",
                        target=target,
                        config={"offset": 0, "write_policy": "if_empty"},
                        current=blank,
                        expected=expected,
                    )
                )
            scenarios.append(
                self._scenario(
                    f"{target} preserves an existing value under the empty-only policy",
                    target=target,
                    config={"offset": 1, "write_policy": "if_empty"},
                    current=populated,
                )
            )
            for invalid in ("1.5", "-0.1", "tomorrow", True, [1], {"value": 1}):
                scenarios.append(
                    self._scenario(
                        f"{target} rejects the noninteger offset {invalid!r}",
                        target=target,
                        config={"offset": invalid},
                        error="Enter a whole number",
                    )
                )
            for config in ({}, {"offset": None}, {"offset": ""}):
                scenarios.append(
                    self._scenario(
                        f"{target} requires an explicit offset: {config!r}",
                        target=target,
                        config=config,
                        error="This field is required",
                    )
                )
            for policy in ("replace", "if_empty_or_zero", "invalid"):
                scenarios.append(
                    self._scenario(
                        f"{target} rejects unsupported policy {policy}",
                        target=target,
                        config={"offset": 0, "write_policy": policy},
                        error="Select a valid choice",
                    )
                )
            for offset in (10**20, -(10**20)):
                scenarios.append(
                    self._scenario(
                        f"{target} reports an out-of-range offset {offset}",
                        target=target,
                        config={"offset": offset},
                        error="outside the supported range",
                    )
                )
        for target in (
            "name",
            "amount",
            "clock",
            "readonly_date",
            "created_at",
            "lines",
        ):
            scenarios.append(
                self._scenario(
                    f"reject ineligible target {target}",
                    target=target,
                    config={"offset": 1},
                    error="editable scalar date or datetime",
                )
            )
        return scenarios

    def test_target_choices_and_registration(self) -> None:
        """Expose the registered action only for editable scalar temporal fields."""
        choices = self.action.get_target_fields(
            ApplicationField.get_for_model(self.relative_model), self._field("name")
        )
        self.assertEqual(
            set(choices.values_list("field", flat=True)), {"due_date", "due_at"}
        )
        self.assertIs(ACTION_REGISTRY.get("set_relative_date"), self.action)

    def test_editor_labels_and_cleaned_configuration(self) -> None:
        """Explain exact units and derive the temporal kind from the selected target."""
        for target, kind, unit, anchor in (
            ("due_date", "date", "days", "today"),
            ("due_at", "datetime", "minutes", "current time"),
        ):
            with self.subTest(target=target):
                form_class = build_action_config_form(
                    self.action, self._field("name"), self._field(target)
                )
                offset = form_class.base_fields["offset"]
                self.assertEqual(offset.label, f"Offset ({unit})")
                self.assertIn(f"Whole {unit}", offset.help_text)
                self.assertIn(anchor, offset.help_text)
                self.assertEqual(offset.initial, 0)
                cleaned = clean_action_config(
                    self.action,
                    self._field("name"),
                    self._field(target),
                    {"offset": "-2"},
                )
                self.assertEqual(cleaned["offset"], -2)
                self.assertEqual(cleaned["temporal_kind"], kind)
                self.assertEqual(cleaned["write_policy"], "always")
        with self.assertRaisesRegex(ValidationError, "Select a target field"):
            self.action.config_form_factory(None, self._field("name"))
